for (let stepIndex = startStep; stepIndex <= loop.budget.granted; stepIndex += 1) {
    try {
        const outcome = await this.#step(loop, stepIndex);
        if (outcome)
            return outcome;
        if (loop.failure === undefined)
            failures = 0;
    }
    catch (error) {
        if (!recoverable(error, loop.turn.signal))
            throw error;
        failures += 1;
        const code = classifyError(error).code;
        if (failures > STEP_RETRIES + 1)
            return failureFallback(loop, stepIndex + 1, code);
        if (failures > STEP_RETRIES)
            loop.failure = code;
        loop.budget.grantRecoveryStep(stepIndex);
    }
}

